'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { useEffect, useId, useRef, useState } from 'react';

import {
  CircleAlertIcon,
  CircleCheckIcon,
  PaperclipIcon,
  UploadCloudIcon,
} from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import {
  FileUpload,
  FileUploadContent,
  useFileUpload,
} from '@/registry/ndeko/ui/chat-file-upload';
import {
  PromptInput,
  PromptInputAction,
  PromptInputActions,
  PromptInputTextarea,
} from '@/registry/ndeko/ui/chat-prompt-input';
import { PromptSuggestion } from '@/registry/ndeko/ui/chat-prompt-suggestion';

import { AttachmentList, formatBytes } from './attachment-list';
import {
  maxBytes,
  maxFiles,
  models,
  seedAttachments,
  sendingMs,
  sentMs,
  suggestions,
  type Attachment,
  type AttachmentKind,
  type ModelValue,
} from './data';
import { ModelPicker } from './model-picker';
import { risePresenceOf } from './presence';
import { SubmitButton, type SubmitPhase } from './submit-button';

type NoticeTone = 'refusal' | 'sent';

type Notice = {
  tone: NoticeTone;
  text: string;
};

const NOTICE_ICON: Record<NoticeTone, React.ReactNode> = {
  refusal: <CircleAlertIcon className='text-warning-foreground size-4' />,
  sent: <CircleCheckIcon className='text-success-foreground size-4' />,
};

function kindOf(file: File): AttachmentKind {
  const isImage = file.type.startsWith('image/');
  if (isImage) {
    return 'image';
  }
  return 'document';
}

function modelLabelOf(value: ModelValue) {
  const model = models.find((candidate) => candidate.value === value);
  return model?.label ?? value;
}

function fileCountOf(count: number) {
  if (count === 1) {
    return '1 file';
  }
  return `${count} files`;
}

function sentTextOf(modelLabel: string, fileCount: number) {
  if (fileCount === 0) {
    return `Sent to ${modelLabel}`;
  }
  const files = fileCountOf(fileCount);
  return `Sent to ${modelLabel} with ${files}`;
}

function refusalOf(tooLargeName: string | null, hasOverflow: boolean) {
  if (tooLargeName) {
    const limit = formatBytes(maxBytes);
    const text = `“${tooLargeName}” is over ${limit}. Attach a smaller copy`;
    return { tone: 'refusal' as const, text };
  }
  if (hasOverflow) {
    const text = `${fileCountOf(maxFiles)} fit in one prompt. Remove one to add another`;
    return { tone: 'refusal' as const, text };
  }
  return null;
}

function focusAtEnd(id: string) {
  const element = document.getElementById(id);
  if (!(element instanceof HTMLTextAreaElement)) {
    return;
  }
  const end = element.value.length;
  element.focus();
  element.setSelectionRange(end, end);
}

type AttachButtonProps = {
  isFull: boolean;
  disabled: boolean;
  onRefuse: () => void;
};

function AttachButton({ isFull, disabled, onRefuse }: AttachButtonProps) {
  const { openPicker } = useFileUpload();

  function attach() {
    if (isFull) {
      onRefuse();
      return;
    }
    openPicker();
  }

  return (
    <PromptInputAction tooltip='Attach files'>
      <Button
        type='button'
        variant='ghost'
        size='icon'
        aria-label='Attach files'
        disabled={disabled}
        onClick={attach}
        className='text-muted-foreground'
      >
        <PaperclipIcon />
      </Button>
    </PromptInputAction>
  );
}

function Composer02() {
  const [draft, setDraft] = useState('');
  const [attachments, setAttachments] = useState<Attachment[]>(seedAttachments);
  const [model, setModel] = useState<ModelValue>('deep');
  const [phase, setPhase] = useState<SubmitPhase>('idle');
  const [notice, setNotice] = useState<Notice | null>(null);
  const idCounter = useRef(0);
  const timers = useRef(new Set<ReturnType<typeof setTimeout>>());
  const textareaId = useId();
  const shouldReduceMotion = useReducedMotion();
  const presence = risePresenceOf(shouldReduceMotion);
  const isIdle = phase === 'idle';
  const isWorking = !isIdle;
  const hasText = draft.trim().length > 0;
  const hasAttachments = attachments.length > 0;
  const canSend = hasText || hasAttachments;
  const isFull = attachments.length >= maxFiles;
  const isDraftEmpty = draft.length === 0;
  const showsSuggestions = isDraftEmpty && isIdle;

  useEffect(() => {
    const pending = timers.current;
    return () => {
      pending.forEach((timer) => clearTimeout(timer));
    };
  }, []);

  function schedule(task: () => void, delay: number) {
    const timer = setTimeout(() => {
      timers.current.delete(timer);
      task();
    }, delay);
    timers.current.add(timer);
  }

  function nextId() {
    idCounter.current += 1;
    return `file-${idCounter.current}`;
  }

  function addFiles(files: File[]) {
    const room = maxFiles - attachments.length;
    const accepted: Attachment[] = [];
    let tooLargeName: string | null = null;
    let hasOverflow = false;
    for (const file of files) {
      const isTooLarge = file.size > maxBytes;
      if (isTooLarge) {
        tooLargeName = file.name;
        continue;
      }
      const isOutOfRoom = accepted.length >= room;
      if (isOutOfRoom) {
        hasOverflow = true;
        continue;
      }
      const attachment: Attachment = {
        id: nextId(),
        name: file.name,
        size: file.size,
        kind: kindOf(file),
      };
      accepted.push(attachment);
    }
    setAttachments((current) => [...current, ...accepted]);
    setNotice(refusalOf(tooLargeName, hasOverflow));
  }

  function removeAttachment(id: string) {
    setAttachments((current) => current.filter((item) => item.id !== id));
    setNotice(null);
  }

  function refuseMoreFiles() {
    setNotice(refusalOf(null, true));
  }

  function changeDraft(value: string) {
    setDraft(value);
    if (notice?.tone === 'sent') {
      setNotice(null);
    }
  }

  function applySuggestion(text: string) {
    setDraft(text);
    requestAnimationFrame(() => focusAtEnd(textareaId));
  }

  function send() {
    if (!isIdle) {
      return;
    }
    if (!canSend) {
      return;
    }
    const modelLabel = modelLabelOf(model);
    const sentText = sentTextOf(modelLabel, attachments.length);
    setPhase('sending');
    setNotice(null);
    schedule(() => {
      setPhase('sent');
      setDraft('');
      setAttachments([]);
      setNotice({ tone: 'sent', text: sentText });
    }, sendingMs);
    schedule(() => setPhase('idle'), sendingMs + sentMs);
  }

  return (
    <div className='bg-background text-foreground flex min-h-dvh w-full flex-col items-center px-4 pt-16 pb-10 sm:pt-24'>
      <div className='w-full max-w-xl'>
        <div className='mb-5 space-y-1.5 text-center'>
          <h1 className='text-xl font-semibold text-balance sm:text-2xl'>
            Draft with Quillstone
          </h1>
          <p className='text-muted-foreground text-sm text-balance'>
            Attach notes or a page, pick a model and say what you need
          </p>
        </div>

        <FileUpload onFilesAdded={addFiles} disabled={isWorking}>
          <PromptInput
            value={draft}
            onValueChange={changeDraft}
            onSubmit={send}
            isLoading={isWorking}
          >
            <AnimatedSize>
              <AttachmentList
                attachments={attachments}
                onRemove={removeAttachment}
                disabled={isWorking}
              />
              <PromptInputTextarea
                id={textareaId}
                aria-label='Prompt'
                placeholder='Ask Quillstone to draft, rewrite or summarise'
                readOnly={isWorking}
              />
              <PromptInputActions className='justify-between gap-2 pt-1'>
                <div className='flex min-w-0 items-center gap-1'>
                  <AttachButton
                    isFull={isFull}
                    disabled={isWorking}
                    onRefuse={refuseMoreFiles}
                  />
                  <ModelPicker
                    value={model}
                    onChange={setModel}
                    disabled={isWorking}
                  />
                </div>
                <SubmitButton phase={phase} canSend={canSend} onSend={send} />
              </PromptInputActions>
            </AnimatedSize>
          </PromptInput>
          <FileUploadContent>
            <div className='bg-card hairline-border border-foreground/25 flex flex-col items-center gap-2 rounded-2xl border-dashed px-10 py-8 text-center shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
              <UploadCloudIcon className='text-muted-foreground size-6' />
              <p className='text-sm font-medium'>Drop files to attach them</p>
              <p className='text-muted-foreground text-xs'>
                Up to {fileCountOf(maxFiles)}, {formatBytes(maxBytes)} each
              </p>
            </div>
          </FileUploadContent>
        </FileUpload>

        <AnimatedSize>
          <div aria-live='polite'>
            <AnimatePresence initial={false} mode='popLayout'>
              {notice && (
                <motion.p
                  key={notice.text}
                  className='text-muted-foreground flex items-start gap-2 px-1 pt-3 text-[13px]'
                  {...presence}
                >
                  <span className='mt-px shrink-0'>
                    {NOTICE_ICON[notice.tone]}
                  </span>
                  {notice.text}
                </motion.p>
              )}
            </AnimatePresence>
          </div>
        </AnimatedSize>

        <AnimatePresence initial={false}>
          {showsSuggestions && (
            <motion.ul
              key='suggestions'
              aria-label='Suggested prompts'
              className='mt-4 flex flex-wrap justify-center gap-2'
              {...presence}
            >
              {suggestions.map((suggestion) => (
                <li key={suggestion}>
                  <PromptSuggestion onClick={() => applySuggestion(suggestion)}>
                    {suggestion}
                  </PromptSuggestion>
                </li>
              ))}
            </motion.ul>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

export default Composer02;

'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';

import { FileTextIcon, ImageIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';

import type { Attachment, AttachmentKind } from './data';
import { layoutTransitionOf, settlePresenceOf } from './presence';

const KILOBYTE = 1024;

const MEGABYTE = KILOBYTE * 1024;

const KIND_LOOK: Record<
  AttachmentKind,
  { icon: React.ReactNode; gem: string }
> = {
  document: { icon: <FileTextIcon />, gem: 'var(--primary)' },
  image: { icon: <ImageIcon />, gem: 'var(--info)' },
};

export function formatBytes(size: number) {
  if (size < KILOBYTE) {
    return `${size} B`;
  }
  if (size < MEGABYTE) {
    const kilobytes = Math.round(size / KILOBYTE);
    return `${kilobytes} KB`;
  }
  const tenths = Math.round((size / MEGABYTE) * 10);
  const megabytes = tenths / 10;
  return `${megabytes} MB`;
}

type AttachmentListProps = {
  attachments: Attachment[];
  onRemove: (id: string) => void;
  disabled?: boolean;
};

export function AttachmentList({
  attachments,
  onRemove,
  disabled = false,
}: AttachmentListProps) {
  const shouldReduceMotion = useReducedMotion();
  const presence = settlePresenceOf(shouldReduceMotion);
  const layoutTransition = layoutTransitionOf(shouldReduceMotion);
  const transition = { ...presence.transition, layout: layoutTransition };
  const hasAttachments = attachments.length > 0;

  return (
    <ul
      aria-label='Attachments'
      className={cn(
        'flex flex-wrap gap-1.5',
        hasAttachments && 'px-1 pt-1 pb-2'
      )}
    >
      <AnimatePresence mode='popLayout' initial={false}>
        {attachments.map((attachment) => {
          const look = KIND_LOOK[attachment.kind];
          const plateStyle = { '--gem': look.gem } as React.CSSProperties;
          const size = formatBytes(attachment.size);

          return (
            <motion.li
              key={attachment.id}
              layout
              initial={presence.initial}
              animate={presence.animate}
              exit={presence.exit}
              transition={transition}
              className='bg-card hairline-ring ring-border flex h-11 max-w-60 items-center gap-2 rounded-lg ps-1.5 pe-1 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
            >
              <span
                aria-hidden='true'
                style={plateStyle}
                className='gem-plate inline-flex size-7 shrink-0 items-center justify-center rounded-md [&_svg]:size-3.5'
              >
                {look.icon}
              </span>
              <span className='min-w-0 flex-1'>
                <span className='block truncate text-xs font-medium'>
                  {attachment.name}
                </span>
                <span className='text-muted-foreground block text-xs tabular-nums'>
                  {size}
                </span>
              </span>
              <Button
                type='button'
                variant='ghost'
                size='icon-sm'
                aria-label={`Remove ${attachment.name}`}
                disabled={disabled}
                onClick={() => onRemove(attachment.id)}
                className='text-muted-foreground'
              >
                <XIcon className='size-3.5' />
              </Button>
            </motion.li>
          );
        })}
      </AnimatePresence>
    </ul>
  );
}

'use client';

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/registry/ndeko/ui/select';

import { models, type ModelValue } from './data';

function isModelValue(value: unknown): value is ModelValue {
  return models.some((model) => model.value === value);
}

type ModelPickerProps = {
  value: ModelValue;
  onChange: (value: ModelValue) => void;
  disabled?: boolean;
};

export function ModelPicker({ value, onChange, disabled }: ModelPickerProps) {
  function change(next: unknown) {
    if (isModelValue(next)) {
      onChange(next);
    }
  }

  return (
    <Select
      items={models}
      value={value}
      onValueChange={change}
      disabled={disabled}
    >
      <SelectTrigger size='sm' aria-label='Model' className='w-auto min-w-32'>
        <SelectValue />
      </SelectTrigger>
      <SelectContent className='min-w-64'>
        {models.map((model) => (
          <SelectItem key={model.value} value={model.value}>
            <span className='shrink-0'>{model.label}</span>
            <span className='text-muted-foreground truncate text-xs'>
              {model.hint}
            </span>
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

'use client';

import { CheckIcon, LoaderIcon, SendIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';

export type SubmitPhase = 'idle' | 'sending' | 'sent';

const PHASE_LABEL: Record<SubmitPhase, string> = {
  idle: 'Send',
  sending: 'Sending',
  sent: 'Sent',
};

function PhaseIcon({ phase }: { phase: SubmitPhase }) {
  if (phase === 'sending') {
    return <LoaderIcon className='animate-spin' />;
  }
  if (phase === 'sent') {
    return <CheckIcon />;
  }
  return <SendIcon />;
}

type SubmitButtonProps = {
  phase: SubmitPhase;
  canSend: boolean;
  onSend: () => void;
};

export function SubmitButton({ phase, canSend, onSend }: SubmitButtonProps) {
  const isIdle = phase === 'idle';
  const isDisabled = isIdle && !canSend;
  const label = PHASE_LABEL[phase];

  function send() {
    if (isIdle) {
      onSend();
    }
  }

  return (
    <Button
      type='button'
      onClick={send}
      disabled={isDisabled}
      aria-live='polite'
      className='px-3'
    >
      <AnimatedSize as='span' axis='width' contentClassName='flex items-center'>
        <Swap swapKey={phase}>
          <span className='flex items-center gap-1.5'>
            <PhaseIcon phase={phase} />
            {label}
          </span>
        </Swap>
      </AnimatedSize>
    </Button>
  );
}

import type { MotionProps, Transition } from 'motion/react';

type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const EASE_OUT_STRONG: [number, number, number, number] = [0.23, 1, 0.32, 1];

const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const EXIT: Transition = { duration: 0.14, ease: EASE_OUT_STRONG };

const SETTLE_PRESENCE: PresenceProps = {
  initial: { opacity: 0, scale: 0.95 },
  animate: { opacity: 1, scale: 1 },
  exit: { opacity: 0, scale: 0.95, transition: EXIT },
  transition: ENTER,
};

const RISE_PRESENCE: PresenceProps = {
  initial: { opacity: 0, y: 4 },
  animate: { opacity: 1, y: 0 },
  exit: { opacity: 0, y: 4, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

export const LAYOUT_SPRING: Transition = {
  type: 'spring',
  bounce: 0,
  duration: 0.3,
};

export const INSTANT: Transition = { duration: 0 };

export function settlePresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return SETTLE_PRESENCE;
}

export function risePresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return RISE_PRESENCE;
}

export function layoutTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return LAYOUT_SPRING;
}

export type ModelValue = 'swift' | 'deep';

export type Model = {
  value: ModelValue;
  label: string;
  hint: string;
};

export type AttachmentKind = 'document' | 'image';

export type Attachment = {
  id: string;
  name: string;
  size: number;
  kind: AttachmentKind;
};

export const models: Model[] = [
  { value: 'swift', label: 'Quill Swift', hint: 'Quick drafts and rewrites' },
  { value: 'deep', label: 'Quill Deep', hint: 'Careful edits on long pages' },
];

export const suggestions = [
  'Summarise this page in five lines',
  'Rewrite the intro for new hires',
  'Turn my meeting notes into a checklist',
];

export const seedAttachments: Attachment[] = [
  {
    id: 'seed-notes',
    name: 'Interview notes, March.pdf',
    size: 186_000,
    kind: 'document',
  },
];

export const maxFiles = 4;

export const maxBytes = 10 * 1024 * 1024;

export const sendingMs = 1100;

export const sentMs = 1400;
